      last[1] = Math.max(last[1], current[1]);
    } else {
      merged.push(current);
    }
  }

  return merged;
}

function prefixeCommun(tab) {
  if (!tab || tab.length === 0) return "";
  let premier = tab[0];
  for (let i = 0; i < premier.length; i++) {
    const char = premier[i];
    for (let j = 1; j < tab.length; j++) {
      if (tab[j][i] !== char) {
        return premier.substring(0, i);
      }
    }
  }
  return premier;
}

function nombreDeBits1(n) {
  let count = 0;
  while (n > 0) {
    count += n & 1;
    n >>= 1;
  }
  return count;
}

function medianeDeuxTries(a, b) {
  const m = a.length;
  const n = b.length;
  if (m > n) return medianeDeuxTries(b, a);

  let low = 0, high = m;
  while (low <= high) {
    const i = Math.floor((low + high) / 2);
    const j = Math.floor((m + n + 1) / 2) - i;

    if (i < m && b[j-1] > a[i]) {
      low = i + 1;
    } else if (i > 0 && a[i-1] > b[j]) {
      high = i - 1;
    } else {
      let maxLeft = -Infinity;
      if (i === 0) maxLeft = b[j-1];
      else if (j === 0) maxLeft = a[i-1];
      else maxLeft = Math.max(a[i-1], b[j-1]);

      let minRight = Infinity;
      if (i === m) minRight = b[j];
      else if (j === n) minRight = a[i];
      else minRight = Math.min(a[i], b[j]);

      const totalLen = m + n;
      if (totalLen % 2 !== 0) return maxLeft;
      return (maxLeft + minRight) / 2;
    }
  }
}

function plusLongueSousSuiteCroissante(tab) {
  const tails = [];
  for (let x of tab) {
    let i = 0, j = tails.length;
    while (i < j) {
      let mid = Math.floor((i + j) / 2);
      if (tails[mid] < x) i = mid + 1;
      else j = mid;
    }
    if (i === tails.length) tails.push(x);
    else tails[i] = x;
  }
  return tails.length;
}
